export default function config({ spreadsheetId, productsSheet, historySheet, recipient }) {
  for (const [k, v] of Object.entries({ spreadsheetId, productsSheet, historySheet, recipient }))
    if (typeof v !== "string" || !v.trim() || v.startsWith("YOUR_")) throw Error("Configure " + k);
  if (
    productsSheet === historySheet ||
    /[!\r\n]/.test(productsSheet + historySheet) ||
    !/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(recipient) ||
    /[\x00-\x1f\x7f]/.test(recipient)
  )
    throw Error("Invalid sheet names or recipient");
  const quote = (s) => "'" + s.replace(/'/g, "''") + "'";
  return {
    spreadsheetId,
    productsSheet,
    recipient,
    productsRange: quote(productsSheet) + "!A:ZZZ",
    historyRange: quote(historySheet) + "!A:C",
  };
}

