export default function rows({ values, sheetName }) {
  if (typeof sheetName !== "string" || !sheetName.trim() || sheetName.includes("!"))
    throw Error("Configure the products sheet name");
  if (!Array.isArray(values)) throw Error("Invalid sheet data");
  if (!values.length) return { items: [], sheetName };
  const h = values[0],
    required = [
      "asin",
      "name",
      "pricing",
      "product_url",
      "alert_status",
      "last_updated",
      "price_change",
      "average_rating",
      "percent_change",
      "alert_threshold_low",
      "alert_threshold_high",
    ];
  if (
    !Array.isArray(h) ||
    required.some((k) => h.indexOf(k) < 0 || h.lastIndexOf(k) !== h.indexOf(k))
  )
    throw Error("Sheet requires unique product headers");
  const indexes = Object.fromEntries(required.map((k) => [k, h.indexOf(k)])),
    items = [],
    ids = new Set();
  for (let i = 1; i < values.length; i++) {
    const r = values[i];
    if (!Array.isArray(r)) throw Error("Malformed row");
    if (!r.some((x) => x !== null && x !== "")) continue;
    const asin = String(r[indexes.asin] ?? "").trim();
    if (!/^[A-Z0-9]{10}$/.test(asin) || ids.has(asin))
      throw Error("Each product requires a unique 10-character ASIN");
    ids.add(asin);
    const low = Number(r[indexes.alert_threshold_low]),
      high = Number(r[indexes.alert_threshold_high]);
    if (
      r[indexes.alert_threshold_low] === "" ||
      r[indexes.alert_threshold_low] == null ||
      r[indexes.alert_threshold_high] === "" ||
      r[indexes.alert_threshold_high] == null ||
      !Number.isFinite(low) ||
      !Number.isFinite(high) ||
      low >= high
    )
      throw Error("Invalid alert thresholds");
    const prior = r[indexes.pricing];
    if (prior !== "" && prior != null && (!Number.isFinite(Number(prior)) || Number(prior) < 0))
      throw Error("Invalid previous price");
    items.push({
      asin,
      index: i + 1,
      raw: r,
      indexes,
      low,
      high,
      prior: prior == null || prior === "" ? null : Number(prior),
    });
  }
  return { items, sheetName: sheetName.trim() };
}

