export default function next({ items, previous, sheetName }) {
  const index = previous?.index ?? 0;
  if (index >= items.length)
    return {
      state: { index },
      more: false,
      asin: "UNUSED0000",
      url: "https://www.amazon.com/dp/UNUSED0000",
      item: {},
      rowRange: "'unused'!A1:ZZZ1",
    };
  const item = items[index],
    name = "'" + sheetName.replace(/'/g, "''") + "'";
  return {
    state: { index: index + 1 },
    more: true,
    asin: item.asin,
    url: "https://www.amazon.com/dp/" + item.asin,
    item,
    rowRange: name + "!A" + item.index + ":ZZZ" + item.index,
  };
}

