export default function parse({ body, asin }) {
  if (!body || typeof body !== "object" || !body.data || typeof body.data !== "object")
    throw Error("Invalid ScrapeOps response");
  const d = body.data;
  if (
    typeof asin !== "string" ||
    !/^[A-Z0-9]{10}$/.test(asin) ||
    d.product_information?.ASIN !== asin
  )
    throw Error("Returned product ASIN does not match request");
  if (d.pricing === null || d.pricing === undefined || d.pricing === "")
    return { valid: false, product: {} };
  if (
    typeof d.pricing !== "string" ||
    !/^\$?\s*(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d{1,2})?$/.test(d.pricing.trim())
  )
    throw Error("Ambiguous US dollar price");
  const price = Number(d.pricing.replace(/[$,\s]/g, ""));
  if (!Number.isFinite(price) || price <= 0) return { valid: false, product: {} };
  if (
    typeof d.name !== "string" ||
    !d.name.trim() ||
    d.name.length > 300 ||
    /[\x00-\x1f\x7f]/.test(d.name)
  )
    throw Error("Missing product name");
  const rating = d.average_rating;
  if (
    rating != null &&
    rating !== "" &&
    (!Number.isFinite(Number(rating)) || Number(rating) < 0 || Number(rating) > 5)
  )
    throw Error("Invalid product rating");
  return {
    valid: true,
    product: { price, name: d.name.trim(), rating: rating == null ? "" : rating },
  };
}

