export default function plan({ item, product, checked, sheetName }) {
  if (
    !Array.isArray(checked) ||
    checked.length !== 1 ||
    JSON.stringify(checked[0]) !== JSON.stringify(item.raw)
  )
    throw Error("Product row changed during lookup");
  const q = "'" + sheetName.replace(/'/g, "''") + "'",
    col = (n) => {
      let x = n + 1,
        s = "";
      while (x) {
        x--;
        s = String.fromCharCode(65 + (x % 26)) + s;
        x = Math.floor(x / 26);
      }
      return s;
    },
    at = (k) => q + "!" + col(item.indexes[k]) + item.index,
    delta = item.prior === null ? 0 : product.price - item.prior,
    ratio = item.prior === null || item.prior === 0 ? 0 : delta / item.prior,
    alert = ratio > item.high ? "High" : ratio < item.low ? "Low" : "",
    timestamp = new Date().toISOString(),
    url = "https://www.amazon.com/dp/" + item.asin,
    values = {
      name: product.name,
      pricing: product.price,
      product_url: url,
      alert_status: alert,
      last_updated: timestamp,
      price_change: delta,
      average_rating: product.rating,
      percent_change: ratio,
    },
    data = Object.entries(values).map(([k, v]) => ({ range: at(k), values: [[v]] }));
  return {
    data,
    history: [[item.asin, product.price, timestamp]],
    alert: !!alert,
    subject: "Amazon price alert: " + product.name,
    body:
      "ASIN: " +
      item.asin +
      "\nPrevious price: " +
      (item.prior === null ? "not available" : item.prior) +
      "\nCurrent price: " +
      product.price +
      "\nChange: " +
      delta +
      " (" +
      (ratio * 100).toFixed(2) +
      "%)\n" +
      url,
  };
}

